interface.definition:
a!localVariables(
  local!nominationTypes:#"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050345"(
    refTypeId: {
      #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3595675"
    },
    returnCDT: true
  ),
  local!nominationTypeId:if(
    isusermemberofgroups(
      loggedInUser(),
      #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3174922"
    ),
    ri!nomination.nominationTypeId,
    #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4233557"
  ),
  local!nominationTypesToDisplay:if(
    isusermemberofgroups(
      loggedInUser(),
      #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3174922"
    ),
    local!nominationTypes,
    index(
      local!nominationTypes,
      wherecontains(
        #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4233557",
        property(local!nominationTypes,"refId",tointeger(null))
      ),
      null
    )
  ),

  #"SYSTEM_SYSRULES_formLayout_v1"(
    label: "Start Nomination",
    contents: {
      #"SYSTEM_SYSRULES_boxLayout"(
        label: "Nomination Type",
        contents: {
          #"SYSTEM_SYSRULES_columnsLayout"(
            columns: {
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_radioButtonField"(
                    label: "",
                    labelPosition: "ABOVE",
                    choiceLabels: property(local!nominationTypesToDisplay,"description",null),
                    choiceValues: property(local!nominationTypesToDisplay,"refId",null),
                    value: local!nominationTypeId,
                    saveInto: {
                      ri!nomination.nominationTypeId
                    },
                    choiceLayout: "STACKED",
                    validations: {}
                  )
                }
              ),
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: {}
              )
            }
          )
        },
        style: "ACCENT"
      )
    },
    buttons:{
      #"SYSTEM_SYSRULES_ButtonLayout"(
        primaryButtons: #"SYSTEM_SYSRULES_ButtonWidget"(
          label: "Start Nomination",
          style:"PRIMARY",
          confirmMessage:"Do you want to start nomination?",
          submit: true,
          value:#"_a-0000e676-ab43-8000-9bf5-011c48011c48_3155707",
          saveInto: {
            ri!action,
            a!save(
              ri!nomination.nominationTypeId,
              local!nominationTypeId
            )
          },
          disabled: if(
            local!nominationTypeId = #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4233557",
            false,
            #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(property(ri!nomination,"nominationTypeId",null))
          )
        ),
        secondaryButtons: #"SYSTEM_SYSRULES_ButtonWidget"(
          label: #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3602779",
          style:"DESTRUCTIVE",
          confirmMessage:"Are you sure you want to exit? Your changes will not be saved.",
          confirmButtonLabel: #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3602779",
          confirmHeader: "Warning!",
          submit: true,
          value: #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3602779",
          saveInto: {ri!action}
        )
      )
    }
  )
)
